//
//  FocusSession+Reflection.swift
//  NoFeed
//
//  `reflectionRaw` is the stored column (generated by Core Data codegen, so it
//  is not declared here). `rating` is the retired 1–5 column, still present on
//  every install that had it. Reading falls through to the legacy value, so
//  old sessions keep their answer without a migration pass; writing only ever
//  touches the new column.
//

import CoreData

extension FocusSession {
    var reflection: SessionReflection {
        get {
            if let stored = SessionReflection(rawValue: reflectionRaw), stored != .none {
                return stored
            }
            return .fromLegacyRating(rating)
        }
        set {
            reflectionRaw = newValue.rawValue
        }
    }
}
